package io.github.diodeme.ji.error;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.time.Duration;
import java.util.Map;
import java.util.Optional;
import java.util.OptionalLong;
import org.junit.jupiter.api.Test;

final class JiErrorTest {
    @Test
    void errorContainsOnlyStructuredTransportNeutralFields() {
        var error = new JiError(ErrorCode.QUEUE_REVISION_CONFLICT,
                Map.of("expectedRevision", "4"), Optional.of("trace-1"),
                Optional.of(Duration.ofSeconds(2)), OptionalLong.of(5));
        assertEquals("queue.revision_conflict", error.code().code());
        assertEquals(5, error.currentRevision().orElseThrow());
    }

    @Test
    void negativeRetryAfterIsRejected() {
        assertThrows(IllegalArgumentException.class, () -> new JiError(
                ErrorCode.PROVIDER_TIMEOUT, Map.of(), Optional.empty(),
                Optional.of(Duration.ofMillis(-1)), OptionalLong.empty()));
    }
}
